//! Manual journal entries: the accountant-facing way to build a
//! `Transaction` directly, rather than one generated by another domain
//! (a sales invoice, a bill payment, ...). A journal entry has no storage
//! of its own -- it's a `TransactionType::ManualJournal` transaction like
//! any other, built here with a friendlier API and posted through the
//! same transaction engine as everything else.

use chrono::NaiveDate;
use rust_decimal::Decimal;

use crate::backend::transactions::transaction::Transaction;
use crate::backend::transactions::transaction_lines::TransactionLine;
use crate::backend::transactions::transaction_types::TransactionType;

pub struct JournalEntry {
    transaction: Transaction,
}

impl JournalEntry {
    pub fn new(company_id: i64, entry_date: NaiveDate) -> Self {
        Self {
            transaction: Transaction::new(company_id, TransactionType::ManualJournal, entry_date),
        }
    }

    pub fn with_memo(mut self, memo: impl Into<String>) -> Self {
        self.transaction.description = Some(memo.into());
        self
    }

    pub fn debit(mut self, account_id: i64, amount: Decimal) -> Self {
        self.transaction
            .lines
            .push(TransactionLine::debit(account_id, amount));
        self
    }

    pub fn credit(mut self, account_id: i64, amount: Decimal) -> Self {
        self.transaction
            .lines
            .push(TransactionLine::credit(account_id, amount));
        self
    }

    /// Hands the built transaction over to the transaction engine, via
    /// `AccountingRepository::post_transaction`.
    pub fn into_transaction(self) -> Transaction {
        self.transaction
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::backend::core::validation::Validate;
    use rust_decimal_macros::dec;

    fn date(y: i32, m: u32, d: u32) -> NaiveDate {
        NaiveDate::from_ymd_opt(y, m, d).unwrap()
    }

    #[test]
    fn builds_a_balanced_manual_journal_transaction() {
        let transaction = JournalEntry::new(1, date(2026, 1, 15))
            .with_memo("Owner capital contribution")
            .debit(1, dec!(5000))
            .credit(2, dec!(5000))
            .into_transaction();

        assert_eq!(transaction.transaction_type, TransactionType::ManualJournal);
        assert_eq!(
            transaction.description.as_deref(),
            Some("Owner capital contribution")
        );
        assert!(transaction.validate().is_ok());
    }
}
